using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    static LibraryDocument Registered(Package p)=>new(){Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Executables=["Game.exe"],Scope=StoredScope.Capture(p)}]};
    static (Package Game,string Parent,string Search,ScanSnapshot Scan,FolderCheckpoint Checkpoint) Game(string dir,bool marked=true)
    {
        var search=Path.Combine(dir,"container");var parent=Path.Combine(search,"外側パッケージ","ゲーム名");var data=Path.Combine(parent,"data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllText(Path.Combine(data,"save.dat"),"test save");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=marked,Source=data,DetectedRoot=data,SearchRoot=search,Name="data",Folder="data"};if(marked)LibraryStore.EnsureIdentity(data,p.Id);var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);scan.PrepareIndex();return(p,parent,search,scan,WorkspaceReconciler.Capture(p,scan));
    }
    static string RenameParent(string parent){var renamed=Path.Combine(Path.GetDirectoryName(parent)!,"ゲーム名5555");Directory.Move(parent,renamed);return Path.Combine(renamed,"data");}
    static string Refusal(Action run){try{run();}catch(IOException e){return e.Message;}throw new Exception("Expected refusal");}
    static WorkspaceDocument Plan(string dir,Package p,FolderCheckpoint check,params Package[] others)=>new(){SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=new[]{p}.Concat(others).ToList(),Checkpoints=[check]};
    static Package Helper(string parent)=>new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=parent,DetectedRoot=parent,SearchRoot=Path.GetDirectoryName(parent)!,Folder=Path.GetFileName(parent),Name=Path.GetFileName(parent)};
    static ScanSnapshot Scan(string root){var scan=GameScanner.Scan(root);scan.SearchRoots.Add(root);scan.PrepareIndex();return scan;}
    [STAThread]static int Main(string[] args)
    {
        var root=Path.Combine(args[0],Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> run){var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);try{run(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        Test("added-executable-is-not-a-separate-owned-candidate",dir=>{var p=Fixture(dir);p.Registered=true;var baseline=WorkspaceReconciler.Capture(p,Scan(p.SearchRoot));var extra=Path.Combine(p.Source,"engine");Directory.CreateDirectory(extra);File.WriteAllText(Path.Combine(extra,"New.EXE"),"generated");var scan=Scan(p.SearchRoot);WorkspaceReconciler.Check(p,baseline,scan);Check(p.AddedExecutables.SequenceEqual(new[]{Path.Combine("engine","New.EXE")})&&p.ReviewReason.Contains("실행 파일 1개"),"Added executable summary missing");Check(!WorkspaceReconciler.Discover(scan,[p]).Any(c=>c.Source==extra),"Owned executable duplicated");Check(ExecutableCandidates.Find(p.Source).Candidates.Count==2,"Execution choice missing");WorkspaceReconciler.Check(p,WorkspaceReconciler.Capture(p,scan),scan);Check(p.AddedExecutables.Count==0&&p.ReviewState.Length==0,"Accepted change persists");});
        Test("documents-only-change-does-not-claim-exe-added",dir=>{var p=Fixture(dir);var baseline=WorkspaceReconciler.Capture(p,Scan(p.Source));File.WriteAllText(Path.Combine(p.Source,"new.txt"),"generated");WorkspaceReconciler.Check(p,baseline,Scan(p.Source));Check(p.AddedExecutables.Count==0&&p.ReviewState=="changed"&&!p.ReviewReason.Contains("실행 파일"),"Document classified as executable");});
        Test("known-original-outside-current-search-is-probed",dir=>{var p=Fixture(dir);LibraryStore.EnsureIdentity(p.Source,p.Id);var copy=Path.Combine(dir,"copy");Directory.CreateDirectory(copy);File.Copy(Path.Combine(p.Source,LibraryStore.MarkerName),Path.Combine(copy,LibraryStore.MarkerName));var scan=Scan(copy);var inventory=LibraryStore.Inspect(scan);IdentityProbe.RefreshKnown(inventory,[p.Source],[copy]);Check(inventory.Locations[p.Id].Count==2,"Known original ignored");Check(LibraryStore.ReadIdentity(p.Source)?.GameId==p.Id,"Probe wrote marker");});
        Test("deleted-known-copy-does-not-remain-a-phantom-duplicate",dir=>{var p=Fixture(dir);LibraryStore.EnsureIdentity(p.Source,p.Id);var absent=Path.Combine(dir,"gone");var inventory=LibraryStore.Inspect(Scan(p.Source));inventory.Locations[p.Id].Add(absent);IdentityProbe.RefreshKnown(inventory,[absent],[p.Source]);Check(inventory.Locations[p.Id].Count==1,"Stale duplicate remains");});
        Test("unknown-outside-copy-is-not-claimed-as-searched",dir=>{var p=Fixture(dir);LibraryStore.EnsureIdentity(p.Source,p.Id);var outside=Path.Combine(dir,"outside");Directory.CreateDirectory(outside);File.Copy(Path.Combine(p.Source,LibraryStore.MarkerName),Path.Combine(outside,LibraryStore.MarkerName));var inventory=LibraryStore.Inspect(Scan(p.Source));IdentityProbe.RefreshKnown(inventory,[],[p.Source]);Check(inventory.Locations[p.Id].Count==1,"Unexpected whole PC traversal");});
        Test("backup-change-during-copy-is-not-marked-completed",dir=>{var p=Fixture(dir);var e=new BackupEngine(Path.Combine(dir,"backup"));typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,(Action<string>)(phase=>{if(phase=="backup-copying")File.WriteAllText(Path.Combine(p.Source,"late.dat"),"generated mutation");}));Refusal(()=>e.CreateAsync(p,[]).GetAwaiter().GetResult());Check(e.ListJobs().All(j=>j.Status!="Completed")&&File.Exists(Path.Combine(p.Source,"Game.exe")),"Changed backup succeeded or source lost");});
        Test("direct-manifest-change-during-hashing-is-not-completed",dir=>{var p=Fixture(dir);var e=new BackupEngine(Path.Combine(dir,"records"));bool changed=false;typeof(BackupEngine).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(e,(Action<string>)(phase=>{if(!changed&&phase=="direct-hashed-file"){changed=true;File.WriteAllText(Path.Combine(p.Source,"late.dat"),"generated mutation");}}));Refusal(()=>e.PrepareDirectMoveAsync(p,[]).GetAwaiter().GetResult());Check(e.ListJobs().All(j=>j.Status!="Completed")&&File.Exists(Path.Combine(p.Source,"Game.exe")),"Changed direct manifest succeeded");});
        Test("user-can-explicitly-split-new-executable-folder",dir=>{var p=Fixture(dir);p.Registered=true;LibraryStore.EnsureIdentity(p.Source,p.Id);var child=Path.Combine(p.Source,"OtherGame");Directory.CreateDirectory(child);File.WriteAllText(Path.Combine(child,"Other.exe"),"generated separate game");var scan=Scan(p.Source);var draft=JsonSerializer.Deserialize<Package>(JsonSerializer.Serialize(p))!;CompositionPlan.Assign(draft,child,"game",new(){Id=p.Id,Executable="Game.exe"},scan);var next=CompositionPlan.Apply(draft,[p],scan);var main=next.Single(g=>g.Id==p.Id);var separate=next.Single(g=>g.Source==child);Check(!main.Includes(child)&&separate.Id!=p.Id&&separate.Registered==false&&File.Exists(Path.Combine(child,"Other.exe"))&&LibraryStore.ReadIdentity(p.Source)?.GameId==p.Id,"Explicit split changed files or identity");});
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        void ModalAction(Action invoke,bool accept,string? screenshot=null){bool seen=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(_,_)=>{if(seen)return;var d=Application.Current.Windows.OfType<AppDialog>().LastOrDefault();if(d==null)return;seen=true;if(screenshot!=null){foreach(var e in Logical((DependencyObject)d.Content).OfType<Expander>())e.IsExpanded=true;Layout(d,600,450,screenshot);}if(accept)Click(d.ActionButtons.Last());else d.Close();};timer.Start();try{invoke();}finally{timer.Stop();}Check(seen,"Expected confirmation did not appear");}
        Test("fresh-verification-does-not-trust-normal-cached-snapshot",dir=>{var w=Window(dir,out var p);try{File.WriteAllText(Path.Combine(p.Source,"Returned.exe"),"generated new executable");Task<bool> task=null!;ModalAction(()=>{task=(Task<bool>)Call(w,"VerifyTransferSelectionAsync",new List<Package>{p})!;Wait(task);},false,Path.Combine(root,"changed-before-move.png"));Check(!task.Result&&p.AddedExecutables.Count==1&&File.Exists(Path.Combine(p.Source,"Returned.exe")),"Cancelled verification changed files or missed new exe");}finally{Close(w);}});
        Test("confirm-current-state-updates-live-and-plan-copy",dir=>{var w=Window(dir,out var p);try{var copy=JsonSerializer.Deserialize<Package>(JsonSerializer.Serialize(p))!;File.WriteAllText(Path.Combine(p.Source,"Returned.exe"),"generated");Task<bool> task=null!;ModalAction(()=>{task=(Task<bool>)Call(w,"VerifyTransferSelectionAsync",new List<Package>{copy})!;Wait(task);},true);Check(task.Result&&p.ReviewState==""&&copy.ReviewState==""&&Get<List<FolderCheckpoint>>(w,"checkpoints").Single().Files.Any(f=>f.RelativePath=="Returned.exe"),"Confirmation not propagated");}finally{Close(w);}});
        Test("additional-executable-dialog-cancel-preserves-baseline",dir=>{var w=Window(dir,out var p);try{var baseline=JsonSerializer.Serialize(Get<List<FolderCheckpoint>>(w,"checkpoints"));File.WriteAllText(Path.Combine(p.Source,"Returned.exe"),"generated");WorkspaceReconciler.Check(p,Get<List<FolderCheckpoint>>(w,"checkpoints").Single(),Scan(p.Source));ModalAction(()=>Call(w,"ReviewAddedExecutables",p),false,Path.Combine(root,"added-executable-review.png"));Check(baseline==JsonSerializer.Serialize(Get<List<FolderCheckpoint>>(w,"checkpoints")),"Cancel accepted scope");}finally{Close(w);}});
        Test("additional-executable-dialog-accept-keeps-one-package",dir=>{var w=Window(dir,out var p);try{File.WriteAllText(Path.Combine(p.Source,"Returned.exe"),"generated");var scan=Scan(p.Source);Set(w,"snapshot",scan);WorkspaceReconciler.Check(p,Get<List<FolderCheckpoint>>(w,"checkpoints").Single(),scan);ModalAction(()=>Call(w,"ReviewAddedExecutables",p),true);Check(p.ReviewState==""&&p.AddedExecutables.Count==0&&Get<List<Package>>(w,"packages").Count==1,"Accept split or failed");}finally{Close(w);}});
        Test("final-intake-rechecks-before-any-registration",dir=>{var w=Window(dir,out var p);try{File.WriteAllText(Path.Combine(p.Source,"Late.exe"),"generated");Set(w,"suppressIntakeResult",true);ModalAction(()=>Wait((Task)Call(w,"ExecuteIntakeAsync",Plan(w,[p]),Path.Combine(dir,"library"))!),false);Check(!File.Exists(Path.Combine(p.Source,LibraryStore.MarkerName))&&!File.Exists(Path.Combine(dir,"library",LibraryStore.JsonName)),"Registration began before recheck accepted");}finally{Close(w);}});
        Test("selected-copy-id-conflict-is-blocked-before-move",dir=>{var w=Window(dir,out var p);try{LibraryStore.EnsureIdentity(p.Source,p.Id);var original=Path.Combine(dir,"original");Directory.CreateDirectory(original);File.Copy(Path.Combine(p.Source,LibraryStore.MarkerName),Path.Combine(original,LibraryStore.MarkerName));Set(w,"libraryDocument",new LibraryDocument{Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=original,Scope=StoredScope.Capture(p)}]});Set(w,"snapshot",Scan(p.Source));Set(w,"checkpoints",new List<FolderCheckpoint>{WorkspaceReconciler.Capture(p,Scan(p.Source))});Task<bool> task=null!;ModalAction(()=>{task=(Task<bool>)Call(w,"VerifyTransferSelectionAsync",new List<Package>{p})!;Wait(task);},false,Path.Combine(root,"duplicate-id-before-move.png"));Check(!task.Result&&p.ReviewState=="identity"&&Directory.Exists(original),"Duplicate was accepted");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
}
